function cn(...values: Array<string | false | undefined>) { return values.filter(Boolean).join(" "); }

function Button({ children, primary, success, danger, small, href }: { children: ReactNode; primary?: boolean; success?: boolean; danger?: boolean; small?: boolean; href?: string }) {
  const cls = cn(styles.button, primary && styles.primary, success && styles.success, danger && styles.danger, small && styles.small);
  return href ? <Link href={href} className={cls}>{children}</Link> : <button type="button" className={cls}>{children}</button>;
}

function Pill({ children, tone = "purple" }: { children: ReactNode; tone?: "green" | "red" | "orange" | "blue" | "purple" | "gray" }) {
  return <span className={cn(styles.pill, tone === "green" && styles.pillGreen, tone === "red" && styles.pillRed, tone === "orange" && styles.pillOrange, tone === "blue" && styles.pillBlue, tone === "purple" && styles.pillPurple)}>{children}</span>;
}

function Person({ name, role }: { name: string; role?: string }) {
  return <span className={styles.person}><Image className={styles.avatar} src={people[name] || people["Michael Chen"]} alt="" width={28} height={28}/><span><b>{name}</b>{role && <span className={styles.cellSub}>{role}</span>}</span></span>;
}

function Header({ title, subtitle, icon, primary = "Create", crumbs = "Projects  ›  TechNova Solutions — Premium Magazine" }: { title: string; subtitle: string; icon?: ReactNode; primary?: string; crumbs?: string }) {
  return <><div className={styles.header}><div><div className={styles.crumbs}>{crumbs}</div><h1>{title} {icon}</h1><p>{subtitle}</p></div><div className={styles.actions}><Button primary><Plus size={14}/>{primary}<ChevronDown size={12}/></Button><Button>Actions <ChevronDown size={12}/></Button><Button><Filter size={13}/>Filters</Button><label className={cn(styles.search,styles.inline)}><Search size={13}/><input aria-label="Search" placeholder="Search records..." style={{border:0,outline:0,width:130}}/></label></div></div></>;
}

function ProjectBar({ stage = "Content Collection", progress = 56, status = "Active", archived = false }: { stage?: string; progress?: number; status?: string; archived?: boolean }) {
  return <div className={cn(styles.card,styles.projectBar)}><div className={styles.projectCell}><div className={styles.projectIdentity}><Image className={styles.projectCover} src={archived ? "/images/articles/daniel-kim.png" : "/images/personal-magazines/arjun-mehta-hero-v2.png"} alt="TechNova Magazine" width={64} height={76}/><div><h2>TechNova Solutions — Premium Magazine</h2><div className={styles.inline}><Pill tone={archived ? "green" : "purple"}>{status}</Pill><span className={styles.muted}>Personal Magazine</span></div><p>Project Code: PRJ-2024-0546</p></div></div></div><div className={styles.projectCell}><span className={styles.label}>Overall Progress</span><strong className={styles.value}>{progress}%</strong><div className={styles.progress}><span style={{width:`${progress}%`}}/></div></div><div className={styles.projectCell}><span className={styles.label}>Current Stage</span><strong className={styles.value}>{stage}</strong><p>Stage 5 of 12</p></div><div className={styles.projectCell}><span className={styles.label}>Target Delivery</span><strong className={styles.value}>Aug 30, 2024</strong><p className={styles.red}>31 days left</p></div><div className={styles.projectCell}><span className={styles.label}>Project Owner</span><Person name="Priya Patel" role="Production"/></div><div className={styles.projectCell}><span className={styles.label}>Account Manager</span><Person name="Arjun Mehta" role="Client Success"/></div></div>;
}

function RouteTabs() {
  const pathname = usePathname();
  return <nav className={styles.tabs}>{projectRoutes.map(([label,href])=><Link key={href} href={href} className={cn(styles.tab,pathname===href&&styles.tabActive)}>{label}</Link>)}</nav>;
}

type Metric = { label: string; value: string; note?: string; icon?: ReactNode };
function Metrics({ items }: { items: Metric[] }) { return <div className={styles.metrics}>{items.map((m,i)=><div className={styles.metric} key={`${m.label}-${i}`}><span className={styles.metricIcon}>{m.icon || <Gauge size={17}/>}</span><span><span className={styles.label}>{m.label}</span><strong>{m.value}</strong><span>{m.note || "Current project"}</span></span></div>)}</div>; }

function FilterBar({ labels = ["All Stages","All Owners","All Departments","All Priorities","All Statuses"] }: { labels?: string[] }) {
  return <div className={styles.filterBar}><div className={styles.filters}>{labels.map(label=><select className={styles.select} key={label} aria-label={label}><option>{label}</option></select>)}<button className={styles.field} type="button"><CalendarDays size={12}/> May 18, 2024 – Aug 30, 2024</button><button className={styles.link} type="button">Reset</button></div><div className={styles.viewButtons}><Button small><ListChecks size={13}/></Button><Button small><BarChart3 size={13}/></Button></div></div>;
}

function DataTable({ columns, rows, selected = 0, minWidth = 1050 }: { columns: string[]; rows: ReactNode[][]; selected?: number; minWidth?: number }) {
  return <div className={styles.tableWrap}><table className={styles.table} style={{minWidth}}><thead><tr><th><input type="checkbox" aria-label="Select all"/></th>{columns.map(c=><th key={c}>{c}</th>)}</tr></thead><tbody>{rows.map((row,i)=><tr key={i} className={i===selected?styles.selected:undefined}><td><input type="checkbox" aria-label={`Select row ${i+1}`}/></td>{row.map((cell,j)=><td key={j}>{cell}</td>)}</tr>)}</tbody></table><Pagination count={rows.length}/></div>;
}

function Pagination({ count = 10 }: { count?: number }) { return <div className={styles.pagination}><span>Showing 1 to {count} of 58 records</span><div className={styles.pages}><button>‹</button><button className={styles.current}>1</button><button>2</button><button>3</button><button>›</button></div><span>Rows per page: <b>10</b></span></div>; }

function DetailPanel({ title, id, icon = <FileText size={19}/>, status = "In Progress", tone = "blue", children, actions }: { title: string; id: string; icon?: ReactNode; status?: string; tone?: Parameters<typeof Pill>[0]["tone"]; children: ReactNode; actions?: ReactNode }) {
  return <aside className={cn(styles.card,styles.pad)}><div className={styles.detailHeader}><div className={styles.detailTitle}><span className={styles.detailIcon}>{icon}</span><div><div className={styles.inline}><h2>{title}</h2><Pill tone={tone}>{status}</Pill></div><span className={styles.muted}>{id}</span></div></div><MoreHorizontal size={17}/></div>{children}{actions&&<div className={styles.section}><h3>Quick Actions</h3><div className={styles.quickGrid}>{actions}</div></div>}</aside>;
}

function Card({ title, action, children, className }: { title: string; action?: string; children: ReactNode; className?: string }) { return <section className={cn(styles.card,styles.pad,className)}><div className={styles.cardHeader}><h2>{title}</h2>{action&&<button type="button">{action} →</button>}</div>{children}</section>; }

function TitleCell({ title, sub }: { title: string; sub?: string }) { return <div><div className={styles.cellTitle}>{title}</div>{sub&&<div className={styles.cellSub}>{sub}</div>}</div>; }

